# -*- coding: utf-8 -*-
"""Cau hoi module 06 (Electronic Displays). Moi cau co du ca ban VI va EN ngay trong item (opts_en, explain_en)
de tranh loi ban EN dung lai chu VI. 'correct' la INDEX trong opts goc (build_quiz.py se xao vi tri, dong thoi xao opts_en).

Nguon Tooley: Ch.1 (28 cau, bo cau 20), Ch.11 (16 cau), Ch.15 (14 cau, chon 10 cau ve hien thi/EFIS/ECAM/ACARS/CMC).
Dap an doc truc tiep tu anh scan Appendix 3 (A.1 trang 376, A.11 trang 380, A.15 trang 381)."""

def T(num, ch, vi, en, opts_vi, opts_en, correct, ev, ee, img=None, note=None):
    d = dict(q=vi, en=en, opts=opts_vi, opts_en=opts_en, correct=correct, explain=ev, explain_en=ee,
             src=f"Tooley Ch.{ch} Q{num}")
    if img: d["img"] = img
    return d

