def F(src, vi, en, opts_vi, opts_en, correct, ev, ee):
    s_en = (src.replace("tr.", "p.").replace("đáp án", "answer").replace("mục", "section").replace("Bảng", "Table"))
    return dict(q=vi, en=en, opts=opts_vi, opts_en=opts_en, correct=correct, explain=ev, explain_en=ee, src=src, src_en=s_en)

